function renderProjects(){return `${header('05','Progetti','Trasforma un soggetto in un piano: setup, sito, condizioni minime e finestre possibili.','<button class="button" data-action="new-project">+ Nuovo progetto</button>')}<div class="grid two-col" style="margin-bottom:14px"><section class="card"><div class="card-head"><h2>Pianificazione sessione</h2><span>progetti salvati</span></div><p style="font-size:11px;color:#7b7d75;line-height:1.6;margin:0">Ogni progetto conserva soggetto, attrezzatura, luogo, obiettivo di integrazione e limiti meteo. Le prossime finestre combinano stagione, altezza culminante e fase lunare; il meteo diventa attendibile solo nel breve periodo.</p></section><section class="card"><div class="card-head"><h2>Passi di una sessione</h2><span>checklist</span></div><div class="activity"><i>01</i><span>Soggetto e composizione nel tuo campo</span></div><div class="activity"><i>02</i><span>Notte, luna e meteo accettabile</span></div><div class="activity"><i>03</i><span>Gear, alimentazione e acquisizione</span></div></section></div>${state.projects.length?state.projects.map(p=>`<article class="project-card" data-project="${p.id}"><i class="project-color"></i><div class="project-main"><h3>${esc(p.name)}</h3><p>${esc(p.target||'Soggetto da definire')} · ${esc(p.setupName||'setup da scegliere')} · ${esc(p.siteName||'località')}</p><div class="target-meta"><span>obiettivo ${p.hours||4} h</span><span>luna max ${p.moon||35}%</span><span>altezza min ${p.alt||30}°</span></div></div><aside>APRI<br><b style="font:20px var(--serif)">↗</b></aside></article>`).join(''):'<section class="card empty">Non hai ancora progetti. Parti da un soggetto nell’atlante o crea un obiettivo annuale.</section>'}<div class="grid two-col" style="margin-top:16px"><section class="card"><div class="card-head"><h2>Checklist sessione</h2><button class="text-button" data-action="reset-check">Azzera</button></div>${[['Batterie cariche','battery'],['Contrappesi e barra','weight'],['Alimentazione / cavi','cable'],['Fascia anticondensa','dew2'],['Focheggiatore / maschera','focus2'],['Piano sequenza acquisizione','sequence']].map(([l,k])=>`<label class="switch-row"><span>${l}</span><input type="checkbox" data-check="${k}"></label>`).join('')}</section><section class="card"><div class="card-head"><h2>Strumenti sessione</h2><span>posizione attiva</span></div><div class="activity"><i>◷</i><span>Calendario lunare e finestre notte</span><button class="text-button" data-go="calendar">Apri</button></div><div class="activity"><i>☁</i><span>Previsioni 7–16 giorni da Open-Meteo</span><button class="text-button" data-go="sites">Apri</button></div><div class="activity"><i>⌖</i><span>Coordinate per puntamento e scheda target</span></div></section></div>`}
function localDateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function projectEventsFor(d){const key=localDateKey(d);return state.projects.filter(p=>p.start&&key>=p.start&&(!p.end||key<=p.end)&&(!p.weekdays?.length||p.weekdays.includes(d.getDay()))).slice(0,2)}
let skyData=null,skyCenter={az:180,alt:55},skySpan=90,skyDrag=null,skyBodyPositions=[];
function renderSky(){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite;const selected=catalog.find(o=>o.id===window._skyTargetId)||null;const f=fovData(),now=new Date(),local=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16);return `${header('03','Planetario',`Mappa del cielo sopra ${esc(site.name)}. Trascina per orientarti; scegli un soggetto per centrarlo e confrontarlo con il tuo campo.`)}<section class="sky-layout"><div class="sky-main"><div class="sky-tools"><label>SITO<select class="select" id="sky-site">${state.sites.map(s=>`<option value="${s.id}" ${s.id===site.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>DATA E ORA<input class="select" id="sky-time" type="datetime-local" value="${local}"></label><label>CAMPO VISIVO <span id="sky-span-label">${skySpan}°</span><input id="sky-span" type="range" min="35" max="110" value="${skySpan}"></label><button class="button light small" id="sky-now">Ora</button><button class="button light small" id="sky-compass">Orientamento</button></div><div class="sky-chart-wrap"><canvas id="sky-canvas" role="img" aria-label="Carta stellare orizzontale interattiva"></canvas><div class="sky-overlay" id="sky-status">${esc(site.name)} · ${site.lat.toFixed(2)}°, ${site.lon.toFixed(2)}°</div></div><div class="sky-legend"><span><i class="star-dot"></i> stelle</span><span><i class="dso-dot"></i> oggetti deep sky</span><span><i class="planet-dot"></i> pianeti e Luna</span><span><i class="frame-dot"></i> campo del setup</span><span>linee: costellazioni IAU</span></div><p class="sky-note">Mappa altazimutale geolocalizzata. Le stelle sotto l’orizzonte non sono mostrate. Posizioni planetarie approssimate; per la puntatura usa un planetario o un software di controllo.</p></div><aside class="sky-side"><section class="night-summary sky-search-panel"><label for="sky-target-search">CERCA UN SOGGETTO</label><input class="search" id="sky-target-search" autocomplete="off" placeholder="Nome comune, M31, NGC…" value="${selected?esc(selected.name):''}"><div id="sky-target-results" class="sky-target-results" hidden></div></section><section class="night-summary sky-selected" id="sky-selected">${selected?skySelectedCard(selected,f):window._skyBodyTarget?skyBodyCard(window._skyBodyTarget):`<div class="card-head"><h2>Seleziona un oggetto</h2><button class="text-button" data-go="catalog">Apri catalogo →</button></div><p>Seleziona un pianeta o un oggetto deep sky sulla mappa, oppure cerca nel catalogo. Il riquadro mostra le proporzioni del tuo setup.</p>${f?`<div class="sky-frame-stats"><b>${f.w.toFixed(2)}° × ${f.h.toFixed(2)}°</b><span>diagonale ${f.diag.toFixed(1)}′ · ${f.scale?f.scale.toFixed(2)+'″/px':'scala n.d.'}</span></div>`:'<button class="button light small" data-go="gear">Configura camera e telescopio</button>'}`}</section><section class="night-summary sky-quick"><div class="card-head"><h2>Inquadratura</h2><span>${f?esc(state.gear.find(x=>x.kind==='Telescope')?.name||'Setup'): 'Setup da completare'}</span></div>${f?`<div class="sky-frame-stats"><b>${f.w.toFixed(2)}° × ${f.h.toFixed(2)}°</b><span>diagonale ${f.diag.toFixed(1)}′ · ${f.scale?f.scale.toFixed(2)+'″/pixel':'campionamento n.d.'}</span></div><p>Il rettangolo sulla mappa indica il campo reale del sensore intorno al soggetto selezionato.</p>`:`<p>Aggiungi telescopio e camera per vedere il campo di ripresa sovrapposto.</p><button class="button light small" data-go="gear">Configura setup →</button>`}</section><section class="night-summary"><div class="card-head"><h2>Questa notte</h2><span id="sky-moon">Luna ${moonIllum(now)}%</span></div><p id="sky-object-position">Scegli un soggetto per vedere altezza, azimut e direzione.</p><button class="button light small" data-go="calendar">Fasi lunari e calendario →</button></section></aside></section>`}
