function skySelectedCard(o,f){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite,p=altAz(o.ra,o.dec,site.lat,site.lon,new Date($('#sky-time')?.value||Date.now())),fit=f&&o.size?frameLabel(o):'setup non configurato';return `<div class="card-head"><div><div class="label-tag">${esc(o.subtype||o.type)} · ${esc(o.const)}</div><h2>${esc(o.name)}</h2><small>${esc([o.id,...(o.catalogs||[])].join(' · '))}</small></div><button class="text-button" data-detail="${esc(o.id)}">Scheda ↗</button></div><div class="sky-object-stats"><span><b>${horizonText(p.alt)}</b><small>altezza</small></span><span><b>${azLabel(p.az)}</b><small>direzione · ${p.az.toFixed(0)}°</small></span><span><b>${sizeLabel(o)}</b><small>estensione</small></span><span><b>${moonIllum(new Date($('#sky-time')?.value||Date.now()))}%</b><small>illuminazione lunare</small></span></div><div class="sky-frame-stats"><b>${esc(fit)}</b><span>${f?`${f.w.toFixed(2)}° × ${f.h.toFixed(2)}° · ${f.scale?f.scale.toFixed(2)+'″/px':'scala n.d.'}`:'Imposta un setup per calcolare il campo.'}</span></div><div class="inline-actions"><button class="button" data-action="sky-project" data-target="${esc(o.id)}">Crea progetto</button><a class="button light small" target="_blank" rel="noreferrer" href="https://www.astrobin.com/search/?q=${encodeURIComponent(o.id)}">Foto AstroBin ↗</a></div>`}
function skyBodyCard(body){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite,d=new Date($('#sky-time')?.value||Date.now()),p=altAz(body.ra,body.dec,site.lat,site.lon,d);return `<div class="card-head"><div><div class="label-tag">SISTEMA SOLARE</div><h2>${esc(body.name)}</h2><small>Posizione apparente · coordinate equatoriali J2000-like</small></div></div><div class="sky-object-stats"><span><b>${horizonText(p.alt)}</b><small>altezza</small></span><span><b>${azLabel(p.az)}</b><small>direzione · ${p.az.toFixed(0)}°</small></span><span><b>${body.ra.toFixed(1)}°</b><small>ascensione retta</small></span><span><b>${body.dec>=0?'+':''}${body.dec.toFixed(1)}°</b><small>declinazione</small></span></div><p>La posizione sulla mappa cambia con data, ora e località. Per la Luna l’illuminazione è ${moonIllum(d)}%.</p>`}
