async function initSkyChart(){const canvas=$('#sky-canvas');if(!canvas)return;try{if(!skyData){const [stars,lines,planets]=await Promise.all(['stars-lite.json','constellation-lines.json','planet-elements.json'].map(x=>fetch(`/src/data/${x}`).then(r=>{if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()})));skyData={stars,lines,planets,cacheKey:null}}drawSkyChart()}catch(err){console.error('Planetario OurSky:',err);$('#sky-status').textContent=`Mappa non caricata: ${err?.message||'errore nei dati'}`;return}const site=$('#sky-site'),date=$('#sky-time'),span=$('#sky-span');site.onchange=()=>{state.activeSite=site.value;save();const s=state.sites.find(x=>x.id===site.value)||defaultSite;skyData.cacheKey=null;$('#sky-status').textContent=`${s.name} · ${s.lat.toFixed(2)}°, ${s.lon.toFixed(2)}°`;drawSkyChart()};date.onchange=()=>{skyData.cacheKey=null;drawSkyChart();refreshSkySelected()};span.oninput=()=>{skySpan=+span.value;$('#sky-span-label').textContent=`${skySpan}°`;drawSkyChart()};$('#sky-now').onclick=()=>{const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);date.value=d.toISOString().slice(0,16);skyData.cacheKey=null;drawSkyChart();refreshSkySelected()};$('#sky-compass').onclick=async()=>{try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const p=await DeviceOrientationEvent.requestPermission();if(p!=='granted')throw Error()}window.addEventListener('deviceorientation',e=>{if(e.alpha!==null){skyCenter.az=(360-e.alpha+360)%360;drawSkyChart()}},{once:false});toast('Orientamento del dispositivo attivo')}catch{toast('Orientamento non disponibile o non autorizzato')}};const search=$('#sky-target-search'),results=$('#sky-target-results');search.oninput=()=>{const q=search.value.trim(),terms=q.split(/\s+/).filter(Boolean).map(normalizeAlias);if(!terms.length){results.hidden=true;return}const hits=catalog.filter(o=>terms.every(t=>[o.id,o.name,o.const,...(o.commonNames||[]),...(o.aliases||[]),...(o.catalogs||[])].some(x=>normalizeAlias(x).includes(t)))).slice(0,12);results.innerHTML=hits.map(o=>`<button class="sky-target-hit" data-sky-pick="${esc(o.id)}"><b>${esc(o.name)}</b><small>${esc([o.id,...(o.catalogs||[]).slice(0,3)].join(' · '))}</small></button>`).join('')||'<div class="project-target-empty">Nessun soggetto trovato.</div>';results.hidden=false;$$('[data-sky-pick]',results).forEach(b=>b.onclick=()=>selectSkyTarget(b.dataset.skyPick))};canvas.onpointerdown=e=>{skyDrag={x:e.clientX,y:e.clientY,az:skyCenter.az,alt:skyCenter.alt};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(skyDrag){const rect=canvas.getBoundingClientRect();skyCenter.az=(skyDrag.az-(e.clientX-skyDrag.x)*skySpan/rect.width+360)%360;skyCenter.alt=Math.max(-5,Math.min(90,skyDrag.alt+(e.clientY-skyDrag.y)*skySpan/rect.width));drawSkyChart()}};canvas.onpointerup=e=>{if(!skyDrag)return;const moved=Math.hypot(e.clientX-skyDrag.x,e.clientY-skyDrag.y);skyDrag=null;if(moved<5)pickSkyAt(e)};if(!window._skyResizeBound){window._skyResizeBound=true;window.addEventListener('resize',()=>{if(page==='sky')drawSkyChart()},{passive:true})}if(window._skyTargetId)selectSkyTarget(window._skyTargetId,false)}
function selectSkyTarget(id,focus=true){const o=catalog.find(x=>x.id===id);if(!o)return;window._skyTargetId=id;window._skyBodyTarget=null;const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite,p=altAz(o.ra,o.dec,site.lat,site.lon,new Date($('#sky-time')?.value||Date.now()));skyCenter={az:p.az,alt:Math.max(5,p.alt)};const i=$('#sky-target-search');if(i)i.value=o.name;const r=$('#sky-target-results');if(r)r.hidden=true;const pane=$('#sky-selected');if(pane)pane.innerHTML=skySelectedCard(o,fovData());refreshSkySelected();drawSkyChart()}
