function saveSky(){let s=state.sites.find(x=>x.id===state.activeSite);if(!s)return;s.bortle=$('#bortle-edit')?.value||null;s.sqm=$('#sqm-edit')?.value||null;save();if(page==='sites')render();toast('Qualità cielo salvata')}
async function loadWeather(force=false){const s=state.sites.find(x=>x.id===state.activeSite)||defaultSite;let target=page==='home'?$('#weather-snippet'):$('#weather-full');if(!target)return;if(weatherCache&&!force&&weatherCache.site===s.id){target.innerHTML=weatherHTML(weatherCache.data,page==='home');return}try{let url=`https://api.open-meteo.com/v1/forecast?latitude=${s.lat}&longitude=${s.lon}&daily=weather_code,temperature_2m_min,temperature_2m_max,precipitation_probability_max,sunrise,sunset&hourly=cloud_cover,relative_humidity_2m,wind_speed_10m&forecast_days=14&timezone=auto`;let r=await fetch(url);if(!r.ok)throw new Error();let data=await r.json();if(Number.isFinite(data.elevation)){s.elev=Math.round(data.elevation);save()}weatherCache={site:s.id,data};target=page==='home'?$('#weather-snippet'):$('#weather-full');if(target)target.innerHTML=weatherHTML(data,page==='home');if(page==='sites'&&Number.isFinite(data.elevation))render()}catch{target=page==='home'?$('#weather-snippet'):$('#weather-full');if(target)target.innerHTML='<div class="empty">Previsioni non raggiungibili ora. Controlla la connessione o apri Open-Meteo.</div>'}}
function weatherHTML(d,compact){const i=0,code=d.daily.weather_code[i],label=wx(code);return compact?`<div style="display:flex;align-items:center;gap:14px"><strong class="weather-big">${Math.round(d.daily.temperature_2m_min[i])}° / ${Math.round(d.daily.temperature_2m_max[i])}°</strong><div><div style="font-size:11px">${label}</div><div style="font-size:9px;color:#85877f;margin-top:5px">Nuvole ora ${d.hourly.cloud_cover[new Date().getHours()]??'—'}% · pioggia max ${d.daily.precipitation_probability_max[i]}%</div></div></div><div class="weather-detail"><span>ALBA ${time(d.daily.sunrise[i])}</span><span>TRAMONTO ${time(d.daily.sunset[i])}</span><span>VENTO ${Math.round(d.hourly.wind_speed_10m[new Date().getHours()]||0)} km/h</span></div>`:`<div class="weather-strip">${d.daily.time.slice(0,14).map((date,i)=>`<div class="card weather-day"><div class="label-tag">${new Date(date+'T12:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric'})}</div><div class="weather-day-condition">${wx(d.daily.weather_code[i])}</div><div class="weather-day-temperature">${Math.round(d.daily.temperature_2m_min[i])}° / ${Math.round(d.daily.temperature_2m_max[i])}°</div><div class="weather-day-detail">nuvole ora ${i===0?(d.hourly.cloud_cover[new Date().getHours()]??'—'):'—'}% · pioggia ${d.daily.precipitation_probability_max[i]}%</div></div>`).join('')}</div><div class="weather-detail" style="margin-top:10px"><span>ALBA ${time(d.daily.sunrise[0])}</span><span>TRAMONTO ${time(d.daily.sunset[0])}</span><span>FONTE OPEN-METEO · AGGIORNAMENTO LIVE</span></div>`}
function time(x){return x?.slice(11,16)||'—'}function wx(c){return c===0?'Sereno':c<=2?'Poco nuvoloso':c===3?'Nuvoloso':c<50?'Nebbia':c<70?'Pioviggine':c<80?'Pioggia':'Temporale'}
let calendarOffset=0;function shiftMonth(k){calendarOffset+=k;let d=new Date();d.setDate(1);d.setMonth(d.getMonth()+calendarOffset);const date=d;const start=(new Date(date.getFullYear(),date.getMonth(),1).getDay()+6)%7,days=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();$('#calendar-title').textContent=new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(date);$('.calendar-grid').innerHTML=['LUN','MAR','MER','GIO','VEN','SAB','DOM'].map(w=>`<div class="day" style="min-height:26px;background:#eeece5;font-size:8px;letter-spacing:.1em">${w}</div>`).join('')+Array.from({length:42},(_,i)=>{let n=i-start+1,ok=n>0&&n<=days,dt=new Date(date.getFullYear(),date.getMonth(),n),obs=catalog.filter(o=>isSeason(o,dt)).sort((a,b)=>b.size-a.size)[0];return `<div class="day ${ok?'':'muted'}">${ok?n:''}<span class="moon">${ok?moonEmoji(dt):''}</span>${ok&&n%4===0&&obs?`<span class="event-dot">${obs.id} · ${esc(obs.name)}</span>`:''}${ok?projectEventsFor(dt).map(p=>`<span class="event-dot project-event">${esc(p.name)}</span>`).join(''):''}</div>`}).join('')}
